// --- Função auxiliar para garantir que a imagem tenha bandas válidas ---
function prepararImagemHistograma(imagemOrigem, mascaraAlvo) {
  // Seleciona apenas as bandas existentes e trata valores nulos
  var bandasValidas = imagemOrigem.bandNames().map(function(bandaNome) {
    // Tenta selecionar, se falha ou retorna nulo, substitui por zero
    return imagemOrigem.select(bandaNome).where(mask(mascaraAlvo.ne(null)), 0); 
  });

  if (bandasValidas.size().gt(0)) {
    try {
      var imagemFinal = bandasValidas.toBands();
      return imagemFinal.updateMask(mascaraAlvo.eq(200)); // Aplica o mask correto
    } catch (e) {
      print("Erro ao processar bandeas:", e);
      return ee.Image(0).toInt().updateMask(mascaraAlvo.eq(200)); // Retorna zero se algo der errado
    }
  } else {
    return ee.Image(0).toInt().updateMask(mascaraAlvo.eq(200));
  }
}

